export function translate(language,key,vars={}) {
  const message=MESSAGES[language]?.[key]??MESSAGES['pt-BR'][key];
  if(message===undefined)throw new Error('Missing translation: '+key);
  return message.replace(/\{(\w+)\}/g,(_,name)=>String(vars[name]??'{'+name+'}'));
}

